package com.happybananas.tracezilla.workflow;
import com.happybananas.tracezilla.shopify.ShopifyCatalog;import com.happybananas.tracezilla.tracezilla.TracezillaCatalog;import java.util.*;
public final class CreateTracezillaSkus{private final ShopifyCatalog source;private final TracezillaCatalog target;public CreateTracezillaSkus(ShopifyCatalog s,TracezillaCatalog t){source=s;target=t;}public Map<String,Object> run(boolean dryRun,int limit)throws Exception{if(limit<1)throw new IllegalArgumentException("limit must be positive");var variants=source.readVariants();var existing=target.existingSkuCodes();var seen=new HashSet<String>();var items=new ArrayList<Map<String,Object>>();for(var v:variants.stream().limit(limit).toList()){var id=v.path("id").asText("unknown");var sku=v.path("sku").asText("").trim();if(sku.isEmpty()){items.add(item(id,null,"invalid","Shopify variant does not have an SKU."));continue;}if(existing.contains(sku)){items.add(item(id,sku,"skipped","SKU already exists in tracezilla."));continue;}if(!seen.add(sku)){items.add(item(id,sku,"skipped","Another Shopify variant in this run has the same SKU."));continue;}var payload=new LinkedHashMap<String,Object>();payload.put("sku_code",sku);payload.put("global_name",sku);payload.put("weight_factor_net",1.0);payload.put("weight_factor_gross",1.0);payload.put("unit_of_measure","pcs");payload.put("lot_unit","colli");payload.put("default_uom_conversion",1.0);if(dryRun)items.add(item(id,sku,"would_create","SKU would be created during execution."));else try{target.createSku(payload);existing.add(sku);items.add(item(id,sku,"created","SKU was created in tracezilla."));}catch(Exception e){items.add(item(id,sku,"failed","tracezilla rejected the SKU creation request."));}}var summary=new LinkedHashMap<String,Object>();summary.put("source_count",variants.size());summary.put("selected_count",Math.min(limit,variants.size()));summary.put("processed_count",items.size());for(var s:List.of("created","would_create","skipped","invalid","failed"))summary.put(s+"_count",items.stream().filter(i->s.equals(i.get("status"))).count());summary.put("dry_run",dryRun);summary.put("limit",limit);return Map.of("summary",summary,"items",items);}private static Map<String,Object> item(String id,String sku,String status,String message){var m=new LinkedHashMap<String,Object>();m.put("source_id",id);m.put("sku",sku);m.put("status",status);m.put("message",message);return m;}}
